// The bundled district files (generated by apps/mobile/tools/gen-districts.mjs) are sound: every
// city is in the catalogue, ids are unique, rings are closed and wound per RFC 7946, the districts
// cover the city, neighbours share their borders exactly (no overlaps, no slivers between them, no
// crossing edges), and the data stays small enough to ship in the app bundle.
import { readdirSync, statSync } from 'node:fs';
import path from 'node:path';

import { CITY_CATALOG } from '../../contexts/territory/domain/city-catalog';
import {
  type District,
  districtAreaM2,
  districtBounds,
  districtContains,
  type Ring,
  signedRingAreaM2,
} from '../../contexts/territory/domain/district';
import { H3CellGrid } from '../../h3';
import { bundledDistricts, DISTRICT_CITY_IDS } from '..';
import { DISTRICT_FILES } from '../data';

const DATA = path.join(__dirname, '..', 'data');
const KB = 1024;
/** Per city and in all (minified JSON): the plan's size budget (docs/plans/districts-2026-10-29.md). */
const CITY_BUDGET = 60 * KB;
/** About a quarter above the 16 cities' 477 KB, so a doubling (or a lost simplification) shows. */
const TOTAL_BUDGET = 600 * KB;
/** Share of the city's area the districts cover (as gen-districts.mjs MIN_COVERAGE / MAX_COVERAGE). */
const MIN_COVERAGE = 0.97;
const MAX_COVERAGE = 1.03;

const M_PER_DEG = 111_195;
/**
 * Gap probes allowed per border edge: notches in the city's own edge narrower than 30 m (Opole: 1 of
 * about 1 300 edges). Borders simplified one district at a time failed with 6–7 % of edges (and 80–160
 * overlapping edges per city).
 */
const MAX_GAP_RATE = 0.001;

/**
 * Probe both sides of every border edge of a city's districts, a few metres off its middle:
 * - `overlaps`: the inside probe lies in another district too (two districts claim the spot);
 * - `gaps`: the outside probe lies in no district but a probe 30 m further out lies in another one
 *   (a sliver between two neighbours whose copies of a border differ). The city's own edge mostly
 *   has nothing 30 m out; a narrow notch in it can (Opole has one), hence MAX_GAP_RATE.
 * Edges shorter than 8 m, and probes that land on the same side at a sharp corner, are skipped.
 */
function partitionFaults(districts: readonly District[], nearM = 2, farM = 30) {
  let edges = 0;
  let overlaps = 0;
  let gaps = 0;
  const boxes = districts.map(districtBounds);
  const others = (d: District, lon: number, lat: number) =>
    districts.filter((o, i) => {
      const [w, s, e, n] = boxes[i];
      return o !== d && lon >= w && lon <= e && lat >= s && lat <= n && districtContains(o, lon, lat);
    }).length;
  for (const d of districts) {
    for (const ring of d.polygons.flat()) {
      for (let i = 0; i < ring.length - 1; i++) {
        const [x1, y1] = ring[i];
        const [x2, y2] = ring[i + 1];
        const mx = M_PER_DEG * Math.cos((((y1 + y2) / 2) * Math.PI) / 180);
        const ex = (x2 - x1) * mx;
        const ey = (y2 - y1) * M_PER_DEG;
        const len = Math.hypot(ex, ey);
        if (len < 4 * nearM) {
          continue;
        }
        // Unit normal to the left of the edge, in degrees per metre.
        const nx = -ey / len / mx;
        const ny = ex / len / M_PER_DEG;
        const [cx, cy] = [(x1 + x2) / 2, (y1 + y2) / 2];
        const left = districtContains(d, cx + nx * nearM, cy + ny * nearM);
        const right = districtContains(d, cx - nx * nearM, cy - ny * nearM);
        if (left === right) {
          continue;
        }
        const s = left ? 1 : -1; // towards the inside
        edges++;
        if (others(d, cx + s * nx * nearM, cy + s * ny * nearM) > 0) {
          overlaps++;
        }
        if (
          others(d, cx - s * nx * nearM, cy - s * ny * nearM) === 0 &&
          others(d, cx - s * nx * farM, cy - s * ny * farM) > 0
        ) {
          gaps++;
        }
      }
    }
  }
  return { edges, overlaps, gaps };
}

type P = readonly [number, number];
const orient = (a: P, b: P, c: P) => Math.sign((b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]));
const within = (a: P, b: P, p: P) =>
  Math.min(a[0], b[0]) <= p[0] &&
  p[0] <= Math.max(a[0], b[0]) &&
  Math.min(a[1], b[1]) <= p[1] &&
  p[1] <= Math.max(a[1], b[1]);
const same = (p: P, q: P) => p[0] === q[0] && p[1] === q[1];

/** Do two edges cross, or touch other than at a shared end? Exact on the 5-decimal grid. */
function conflict(a: P, b: P, c: P, d: P): boolean {
  if (same(a, c) || same(a, d) || same(b, c) || same(b, d)) {
    const [p, q, s] = same(a, c) ? [a, b, d] : same(a, d) ? [a, b, c] : same(b, c) ? [b, a, d] : [b, a, c];
    // Meeting at a shared end is fine unless they run along each other from there.
    return orient(p, q, s) === 0 && (q[0] - p[0]) * (s[0] - p[0]) + (q[1] - p[1]) * (s[1] - p[1]) > 0;
  }
  const [o1, o2, o3, o4] = [orient(a, b, c), orient(a, b, d), orient(c, d, a), orient(c, d, b)];
  if (o1 * o2 < 0 && o3 * o4 < 0) {
    return true;
  }
  return (
    (o1 === 0 && within(a, b, c)) ||
    (o2 === 0 && within(a, b, d)) ||
    (o3 === 0 && within(c, d, a)) ||
    (o4 === 0 && within(c, d, b))
  );
}

/** Edges of a city's rings that cross or touch another edge (a shared border counts once). */
function crossingEdges(rings: readonly Ring[]): number {
  const toInt = ([x, y]: readonly [number, number]): P => [Math.round(x * 1e5), Math.round(y * 1e5)];
  const unique = new Map<string, [P, P]>();
  for (const ring of rings) {
    for (let i = 0; i < ring.length - 1; i++) {
      const a = toInt(ring[i]);
      const b = toInt(ring[i + 1]);
      unique.set([a.join(), b.join()].sort().join('|'), [a, b]);
    }
  }
  const minX = (s: [P, P]) => Math.min(s[0][0], s[1][0]);
  const segs = [...unique.values()].sort((s, t) => minX(s) - minX(t));
  let bad = 0;
  for (let i = 0; i < segs.length; i++) {
    const [a, b] = segs[i];
    const maxX = Math.max(a[0], b[0]);
    for (let j = i + 1; j < segs.length && minX(segs[j]) <= maxX; j++) {
      const [c, d] = segs[j];
      if (Math.max(c[1], d[1]) < Math.min(a[1], b[1]) || Math.min(c[1], d[1]) > Math.max(a[1], b[1])) {
        continue;
      }
      if (conflict(a, b, c, d)) {
        bad++;
      }
    }
  }
  return bad;
}

describe('the partition checks themselves', () => {
  const sq = (lon: number, lat: number, w: number): Ring => [
    [lon, lat],
    [lon + w, lat],
    [lon + w, lat + w],
    [lon, lat + w],
    [lon, lat],
  ];
  const d = (id: string, ring: Ring): District => ({ id, cityId: 'pl-test', name: id, polygons: [[ring]] });
  const tenMetres = 10 / (M_PER_DEG * Math.cos((54.3 * Math.PI) / 180)); // east, in degrees

  it('pass two neighbours that share their border', () => {
    expect(partitionFaults([d('a', sq(18.6, 54.3, 0.01)), d('b', sq(18.61, 54.3, 0.01))])).toEqual({
      edges: 8,
      overlaps: 0,
      gaps: 0,
    });
    expect(crossingEdges([sq(18.6, 54.3, 0.01), sq(18.61, 54.3, 0.01)])).toBe(0);
  });

  it('catch two neighbours that overlap by 10 m', () => {
    const b = sq(18.61 - tenMetres, 54.3, 0.01);
    expect(partitionFaults([d('a', sq(18.6, 54.3, 0.01)), d('b', b)]).overlaps).toBe(2);
    expect(crossingEdges([sq(18.6, 54.3, 0.01), b])).toBeGreaterThan(0);
  });

  it('catch a 10 m sliver between two neighbours', () => {
    expect(partitionFaults([d('a', sq(18.6, 54.3, 0.01)), d('b', sq(18.61 + tenMetres, 54.3, 0.01))]).gaps).toBe(2);
  });

  it('catch a district nested in another', () => {
    expect(partitionFaults([d('a', sq(18.6, 54.3, 0.02)), d('b', sq(18.605, 54.305, 0.005))]).overlaps).toBe(4);
  });

  it('catch a ring that crosses itself (a bow tie)', () => {
    const bowTie: Ring = [
      [18.6, 54.3],
      [18.61, 54.31],
      [18.61, 54.3],
      [18.6, 54.31],
      [18.6, 54.3],
    ];
    expect(crossingEdges([bowTie])).toBeGreaterThan(0);
  });
});

describe('bundled districts', () => {
  const files = readdirSync(DATA).filter((f) => f.endsWith('.json'));

  it('index.ts lists exactly the JSON files in data/', () => {
    expect(Object.keys(DISTRICT_FILES).sort()).toEqual(files.map((f) => f.replace(/\.json$/, '')).sort());
    expect(DISTRICT_CITY_IDS).toEqual(Object.keys(DISTRICT_FILES).sort());
  });

  it('stays within the size budget', () => {
    let total = 0;
    for (const f of files) {
      const size = statSync(path.join(DATA, f)).size;
      total += size;
      expect({ f, ok: size <= CITY_BUDGET }).toEqual({ f, ok: true });
    }
    expect(total).toBeLessThanOrEqual(TOTAL_BUDGET);
  });

  describe.each(Object.entries(DISTRICT_FILES))('%s', (cityId, load) => {
    const file = load();
    const districts = bundledDistricts.districtsOf(cityId);

    it('is a catalogue city with named, closed, RFC 7946-wound districts', () => {
      expect(file.cityId).toBe(cityId);
      expect(CITY_CATALOG.some((c) => c.id === cityId)).toBe(true);
      expect(file.districts.length).toBeGreaterThanOrEqual(3);
      expect(new Set(file.districts.map((d) => d.id)).size).toBe(file.districts.length);
      for (const d of districts) {
        expect(d.name.trim()).not.toBe('');
        expect(d.polygons.length).toBeGreaterThan(0);
        for (const [outer, ...holes] of d.polygons) {
          for (const ring of [outer, ...holes]) {
            expect(ring.length).toBeGreaterThanOrEqual(4);
            expect(ring[0]).toEqual(ring.at(-1));
          }
          expect({ d: d.name, outerCcw: signedRingAreaM2(outer) > 0 }).toEqual({ d: d.name, outerCcw: true });
          for (const h of holes) {
            expect({ d: d.name, holeCw: signedRingAreaM2(h) < 0 }).toEqual({ d: d.name, holeCw: true });
          }
        }
        expect(districtAreaM2(d) / 1e6).toBeGreaterThan(0.05);
      }
    });

    it(`covers ${MIN_COVERAGE * 100}–${MAX_COVERAGE * 100} % of the city`, () => {
      const covered = districts.reduce((a, d) => a + districtAreaM2(d), 0) / file.cityAreaM2;
      expect(covered).toBeGreaterThanOrEqual(MIN_COVERAGE);
      expect(covered).toBeLessThanOrEqual(MAX_COVERAGE);
    });

    it('neighbours share their borders: no overlaps, no slivers, no crossing edges', () => {
      const faults = partitionFaults(districts);
      expect(faults.edges).toBeGreaterThan(100);
      expect(faults.overlaps).toBe(0);
      expect(faults.gaps / faults.edges).toBeLessThanOrEqual(MAX_GAP_RATE);
      expect(crossingEdges(districts.flatMap((d) => d.polygons.flat()))).toBe(0);
    });
  });

  it('measures a district as H3 measures the cells whose centre lies in it', () => {
    // A district of about 3 km² in Gdańsk, polyfilled at res 11 the way GetDistrictCoverage counts
    // turf: a fully turfed district reads a share of 1, not more.
    const grid = new H3CellGrid();
    const gdansk = bundledDistricts.districtsOf('pl-gdansk');
    const [d] = [...gdansk].sort((a, b) => Math.abs(districtAreaM2(a) - 3e6) - Math.abs(districtAreaM2(b) - 3e6));
    expect(d).toBeDefined();
    const lons = d.polygons.flatMap((p) => p[0].map((q) => q[0]));
    const lats = d.polygons.flatMap((p) => p[0].map((q) => q[1]));
    const cells = new Set<string>();
    for (let lon = Math.min(...lons); lon <= Math.max(...lons); lon += 0.0001) {
      for (let lat = Math.min(...lats); lat <= Math.max(...lats); lat += 0.0001) {
        cells.add(grid.cellOf({ lat, lon }));
      }
    }
    let m2 = 0;
    for (const c of cells) {
      const { lat, lon } = grid.centroid(c);
      if (districtContains(d, lon, lat)) {
        m2 += grid.areaM2(c);
      }
    }
    expect(m2 / districtAreaM2(d)).toBeGreaterThan(0.99);
    expect(m2 / districtAreaM2(d)).toBeLessThan(1.01);
  });

  it('answers no districts for a city without data, and the same objects on a second read', () => {
    expect(bundledDistricts.districtsOf('xx-nowhere')).toEqual([]);
    const [first] = DISTRICT_CITY_IDS;
    expect(first).toBeDefined();
    expect(bundledDistricts.districtsOf(first)).toBe(bundledDistricts.districtsOf(first));
  });
});
